import React, {Component} from 'react';
import { Card, Col} from 'react-bootstrap';
import { DivCenterPR } from '../../_assets/js/StylesDiv';
import { BTNCircleEdgeLight } from '../../_assets/js/StylesButtom';
import api from '../../_config/api/binance';
import './styles.css';

class Carteira extends Component {
    
    state = {
        criptos: [
            {
            
            }
        ]
    }
        async componentDidMount(){
            const criptos_api = await api.get('cripto');

            this.setState({
                criptos: criptos_api.data
            })
        }

    render () {
        return (
        <>
                <DivCenterPR className="ajust-card">
                    {this.state.criptos.map( cripto =>
                 
                        <Col className="alin-card">
                            <Card>
                                <Card.Img className="confg-img" src={cripto.image} />
                                <Card.Body className="confg-card">
                                    <Card.Title>{cripto.name}</Card.Title>
                                    <Card.Text>{cripto.symbol}</Card.Text>
                                    <Card.Text>{cripto.current_price}</Card.Text>
                                    <BTNCircleEdgeLight></BTNCircleEdgeLight>
                                </Card.Body>
                            </Card>
                        </Col>
                    )}
                </DivCenterPR>
        </>
        )
    }
}

export default Carteira;
